// Botão e LED: o LED acende enquanto o botão estiver apertado
const int botao = 2;
const int led = 8;

void setup() {
  pinMode(botao, INPUT_PULLUP); // resistor interno ligado ao 5 V
  pinMode(led, OUTPUT);
}

void loop() {
  if (digitalRead(botao) == LOW) { // LOW = botão apertado
    digitalWrite(led, HIGH);
  } else {
    digitalWrite(led, LOW);
  }
}

exemplo:
// Botão como interruptor: cada aperto liga ou desliga o LED
const int botao = 2;
const int led = 8;
bool ligado = false;

void setup() {
  pinMode(botao, INPUT_PULLUP);
  pinMode(led, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  if (digitalRead(botao) == LOW) {
    ligado = !ligado;
    digitalWrite(led, ligado);
    Serial.println(ligado ? "LED ligado" : "LED desligado");
    delay(250); // evita contar o mesmo aperto duas vezes
  }
}
